/* Lumi interaction prototype: local sample state only. */
const $=id=>document.getElementById(id);
const uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,7);
const userProfile=saved('lumi-profile',{name:'Thức Tri',email:'thuctri@example.com',level:'Sinh viên năm 4',goal:'Hiểu và vận dụng kiến thức',style:'Giải thích dễ hiểu'});
let records=saved('lumi-library',sources.map((s,i)=>({...s,id:'source'+i,status:'ready',version:1,tags:['CNTT']})));
let notebooks=saved('lumi-notes',[{id:'note0',title:'Khóa và ràng buộc',body:note,kind:'note',page:12}]);
let sessions=saved('lumi-chats',[]),activeSession=null,chatSourceIds=['source0'];
let drafts=saved('lumi-curriculum',{}),completedLessons=saved('lumi-completed',[]),attempts=saved('lumi-attempts',[]);
let cardDeck=saved('lumi-cards',[{id:'card0',q:'Khóa chính có thể chứa NULL không?',a:'Không. Khóa chính phải xác định duy nhất mỗi bản ghi và không chứa NULL.',due:'Ôn tự do'},{id:'card1',q:'Khóa ngoại có vai trò gì?',a:'Tham chiếu khóa của bảng liên quan và bảo đảm toàn vẹn tham chiếu.',due:'Ôn tự do'},{id:'card2',q:'Một bảng có thể có nhiều khóa ngoại không?',a:'Có. Số khóa ngoại phụ thuộc thiết kế và hệ quản trị.',due:'Ôn tự do'}]);
let plans=saved('lumi-plans',[{id:'plan0',title:'Đọc phần khóa ngoại',day:'Thứ hai',minutes:20,done:false}]);
let reminders=saved('lumi-reminders',[]),outlines=saved('lumi-outlines',[{id:'out0',title:'Khóa và ràng buộc',items:['Nhận diện khóa chính và khóa ngoại','Giải thích toàn vẹn tham chiếu','Tự làm 3 câu hỏi luyện tập']}]);
let feedbacks=saved('lumi-feedback',[]),sourceIndex=0,flashIndex=0,flipped=false,videoTime=125,videoPlaying=false,quizMode='practice',quizPicked=[],focusSeconds=25*60,focusRunning=false,focusDeadline=0,focusTimer=null,authMode='login';
const names={home:'Trang chủ',library:'Góc học tập',reader:'Không gian học',course:'Khóa học',quiz:'Luyện tập',personal:'Cài đặt',hub:'Chức năng',history:'Hội thoại',review:'Sổ ôn tập',flashcards:'Flashcard',planner:'Kế hoạch học',focus:'Tập trung',stats:'Tiến độ học',glossary:'Thuật ngữ',outlines:'Đề cương ôn tập',auth:'Tài khoản',video:'Video & transcript',source:'Chi tiết học liệu',notes:'Ghi chú'};
const baseRender=render,baseHome=home,baseLibrary=library,baseReader=reader,baseCourse=course,baseQuiz=quiz,basePersonal=personal,baseSendChat=sendChat,baseCheckQuiz=checkQuiz;
function saveRecords(){persist('lumi-library',records)}
function head(title,desc,action=''){return `<div class="pagehead"><div><div class="eyebrow">LUMI · KHÔNG GIAN HỌC TẬP</div><h1 style="margin-top:9px">${title}</h1><p>${desc}</p></div>${action}</div>`}
function btn(text,action,secondary=false,ic=''){return `<button class="btn ${secondary?'secondary':''}" onclick="${action}">${ic?icon(ic):''}${text}</button>`}
function input(label,id,value='',type='text'){return `<label for="${id}">${label}</label><input id="${id}" type="${type}" value="${esc(value)}" ${type==='email'?'required':''}>`}
function select(label,id,items,value){return `<label for="${id}">${label}</label><select id="${id}">${items.map(x=>`<option ${x===value?'selected':''}>${esc(x)}</option>`).join('')}</select>`}
function empty(text,action=''){return `<div class="empty">${text}${action?'<div class="actionline">'+action+'</div>':''}</div>`}
function saveAllNotes(){persist('lumi-notes',notebooks)}
function modalForm(title,body,submit,label='Lưu'){showModal(`<h2 id="modalTitle">${title}</h2><form class="lumi-form" onsubmit="event.preventDefault();${submit}">${body}<div class="modalactions">${btn('Hủy','closeModal()',true)}<button class="btn" type="submit">${label}</button></div></form>`)}
function confirmDemo(title,body,action){showModal(`<h2 id="modalTitle">${title}</h2><p>${body}</p><div class="modalactions">${btn('Giữ lại','closeModal()',true)}${btn('Xác nhận',action)}</div>`)}
go=function(p){if(p==='reader'&&readerTab==='notes')readingView='assistant';page=p;$('crumb').textContent=names[p]||'Lumi';render();window.scrollTo({top:0,behavior:'smooth'})};
render=function(){const views={home,library,reader,course,quiz,personal,hub,history:historyPage,review:reviewPage,flashcards:flashcardsPage,planner:plannerPage,focus:focusPage,stats:statsPage,glossary:glossaryPage,outlines:outlinesPage,auth:authPage,video:videoPage,source:sourcePage,notes:notesPage};$('app').dataset.page=page;$('main').innerHTML=(views[page]||hub)();hydrate();const group=['reader','course','quiz','source','video','notes','history'].includes(page)?'library':['review','flashcards','planner','focus','stats','glossary','outlines'].includes(page)?'hub':page;document.querySelectorAll('[data-nav]').forEach(x=>x.classList.toggle('active',x.dataset.nav===group));if(page==='focus')paintTimer()};
const featureGroups=[
['Bắt đầu & tài khoản',[['user','Hồ sơ & tài khoản','Đăng nhập, đăng ký, khôi phục và hồ sơ',"go('auth')"],['folder','Học liệu','Thêm, đổi tên, gắn thẻ, phiên bản và xóa',"tab='sources';go('library')"],['book','Khóa học','Tạo khóa, liên kết nguồn và sửa đề cương',"tab='courses';go('library')"]]],
['Học & hỏi',[['spark','Trợ giảng AI','Chọn nhiều nguồn, hỏi, trích dẫn và báo lỗi',"readerTab='chat';readingView='assistant';go('reader')"],['file','Đọc tài liệu','Chuyển trang, đánh dấu và học tiếp',"readerTab='chat';readingView='document';go('reader')"],['play','Video & transcript','Phát mô phỏng, mốc thời gian và ghi chú',"go('video')"],['note','Ghi chú','Ghi chú, highlight, câu hỏi và câu trả lời lưu',"go('notes')"],['clock','Lịch sử hội thoại','Mở lại, đổi tên, xóa cuộc trò chuyện',"go('history')"],['book','Thuật ngữ','Tra cứu và lưu khái niệm theo nguồn',"go('glossary')"]]],
['Luyện & ôn tập',[['quiz','Tạo bài luyện','Chọn nguồn, mức độ và chế độ làm bài',"quizSetup()"],['check','Sổ ôn tập','Lỗi sai, lời giải và luyện lại',"go('review')"],['quiz','Flashcard','Tạo thẻ, lật thẻ, tự đánh giá mức nhớ',"go('flashcards')"],['note','Đề cương ôn tập','Sinh đề cương mẫu và sửa từng mục',"go('outlines')"],['spark','Tự giải thích','Viết theo cách hiểu của bạn, xem phản hồi mẫu',"activeRecall()"]]],
['Tổ chức theo nhu cầu',[['clock','Kế hoạch & mục tiêu','Thêm việc, đánh dấu xong và nhắc học',"go('planner')"],['clock','Đồng hồ tập trung','Chạy, tạm dừng và lưu phiên học',"go('focus')"],['book','Tiến độ & lịch sử','Bài đã học, kết quả luyện và phiên tập trung',"go('stats')"],['sliders','Cài đặt','Ba giao diện, công cụ tùy chọn, dữ liệu',"go('personal')"]]]];
function hub(){return head('Bạn muốn làm gì?','Các chức năng chính dành cho người học. Bấm từng mục để trải nghiệm.')+`<div class="prototype-banner">${icon('info')}Bản giao diện tương tác · Dữ liệu mẫu và dữ liệu bạn nhập được lưu trên trình duyệt. AI, đăng nhập và đồng bộ được mô phỏng.</div>`+featureGroups.map(([title,items])=>`<section class="feature-section"><div class="sectiontitle"><h2>${title}</h2><span class="badge">${items.length} mục</span></div><div class="feature-grid">${items.map(([ic,t,d,a])=>`<button class="feature-card" onclick="${a}"><span class="tileicon">${icon(ic)}</span><strong>${t}</strong><small>${d}</small>${icon('chevron')}</button>`).join('')}</div></section>`).join('')+footer()}
home=function(){let h=baseHome().replace('Chào Thức Tri','Chào '+esc(userProfile.name)).replace("onclick=\"go('reader')\"","onclick=\"readerTab='chat';readingView='assistant';go('reader')\"").replace("onclick=\"startQuiz()\"","onclick=\"quizSetup()\"");return h.replace('<div class="homegrid">',`<div class="home-discover">${icon('spark')}<span><strong>Khám phá đầy đủ Lumi</strong><small>Tài liệu, AI, luyện tập và công cụ tự học.</small></span>${btn('Xem chức năng',"go('hub')",true)}</div><div class="homegrid">`)};
library=function(){let h=baseLibrary();return h.replace('<div class="tabs">',`<div class="actionline library-actions">${btn('Tạo khóa học','openNewCourse()',true,'plus')}${btn('Ghi chú',"go('notes')",true,'note')}${btn('Hội thoại',"go('history')",true,'clock')}</div><div class="tabs">`).replace('Luyện tập khi sẵn sàng','Cấu hình bài luyện').replace('onclick="startQuiz()"','onclick="quizSetup()"')};
sourceRows=function(){const list=records.map((r,i)=>({r,i})).filter(({r})=>!r.deleted&&(!searchTerm||r.title.toLowerCase().includes(searchTerm.toLowerCase())));return list.length?`<div class="source-stack">${list.map(({r,i})=>`<div class="managed-source"><button class="source-row" onclick="viewSource(${i})"><div class="fileicon ${r.type==='VIDEO'?'blue':''}">${esc(r.type)}</div><div class="sourceinfo"><strong>${esc(r.title)}</strong><small>${esc(r.meta)} · v${r.version||1}</small></div><span class="ready">${r.status==='ready'?'Sẵn sàng':r.status==='failed'?'Cần thử lại':'Đang xử lý'}</span></button><button class="source-menu" aria-label="Quản lý ${esc(r.title)}" onclick="sourceIndex=${i};go('source')">${icon('sliders')}</button></div>`).join('')}</div>`:empty('Chưa có học liệu phù hợp.',btn('Thêm học liệu','openUpload()'))};
function viewSource(i){sourceIndex=i;const r=records[i];if(r.status!=='ready'){go('source');return}readerTab='chat';readingView='document';readerPage=saved('lumi-source-page-'+r.id,12);go(r.type==='VIDEO'?'video':'reader')}
openSource=function(type){let i=records.findIndex(r=>r.type===type&&!r.deleted);if(i>=0)viewSource(i)};
openUpload=function(){modalForm('Thêm học liệu',`<p>Thử luồng thêm nguồn. Bản mẫu không tải file hoặc đọc nội dung thực tế.</p>${select('Loại nguồn','uploadKind',['PDF / slide PDF','Video + transcript','DOCX / PPTX (mở rộng)','Liên kết bài viết','Văn bản dán'])}${input('Tên học liệu','uploadTitle')}<label for="protoFile">Chọn file (tùy chọn)</label><input id="protoFile" type="file" accept=".pdf,.mp4,.webm,.docx,.pptx,.txt" onchange="if(this.files[0])document.getElementById('uploadTitle').value=this.files[0].name">${input('Liên kết nguồn (nếu có)','uploadUrl','','url')}<label for="uploadText">Văn bản hoặc transcript (nếu có)</label><textarea id="uploadText" rows="3" placeholder="Dán nội dung tại đây"></textarea>`,"addPrototypeSource()",'Thêm nguồn')};
function addPrototypeSource(){let title=$('uploadTitle').value.trim();if(!title){toast('Bạn nhập tên học liệu nhé.');return}const kind=$('uploadKind').value;records.unshift({id:uid(),title,type:kind.startsWith('Video')?'VIDEO':kind.startsWith('PDF')?'PDF':kind.startsWith('DOCX')?'DOCX':kind.startsWith('Liên')?'WEB':'TEXT',status:'processing',version:1,tags:[],meta:'Nguồn vừa thêm · Mô phỏng xử lý',text:$('uploadText').value,url:$('uploadUrl').value});saveRecords();sourceIndex=0;closeModal();go('source')}
function sourcePage(){const r=records[sourceIndex];if(!r||r.deleted)return head('Học liệu','')+empty('Học liệu đã được xóa khỏi bản mẫu.',btn('Về thư viện',"tab='sources';go('library')"));return head('Chi tiết học liệu',r.title,btn('Thư viện',"tab='sources';go('library')",true))+`<section class="settingcard"><div class="source-status"><span class="fileicon">${r.type}</span><div><h2>${esc(r.title)}</h2><p>${esc(r.meta)} · Phiên bản ${r.version||1}</p></div></div><div class="actionline">${r.status==='ready'?btn('Mở học liệu',`viewSource(${sourceIndex})`):btn(r.status==='failed'?'Thử xử lý lại':'Hoàn tất xử lý mẫu',"completeSource()")}${btn('Đổi tên','renameSource()',true)}${btn('Gắn thẻ','tagSource()',true)}${btn('Thay phiên bản','replaceSource()',true)}${btn('Xóa nguồn','deleteSource()',true)}</div><div class="chipline">${(r.tags||[]).map(t=>`<span class="badge">${esc(t)}</span>`).join('')}</div></section><section class="settingcard" style="margin-top:18px"><h2>Trạng thái xử lý</h2><ol class="timeline"><li>Tiếp nhận file hoặc nội dung</li><li>Trích văn bản và vị trí nguồn</li><li>Chuẩn bị nội dung để hỏi AI</li><li>${r.status==='ready'?'Hoàn tất — có thể mở học liệu':'Chờ hoàn tất trong bản mô phỏng'}</li></ol><p>Đây là các bước minh họa, chưa thực hiện xử lý tài liệu thật.</p><div class="actionline">${btn('Xem tình huống lỗi',"simulateSourceFailure()",true)}${btn('Dùng nguồn để hỏi',"chooseChatSources()",true)}</div></section>`+footer()}
function completeSource(){records[sourceIndex].status='ready';saveRecords();render();toast('Đã hoàn tất trạng thái xử lý mẫu.')}
function simulateSourceFailure(){records[sourceIndex].status='failed';saveRecords();render();toast('Mô phỏng: chưa đọc được nội dung. Bạn có thể thử lại hoặc thay phiên bản.')}
function renameSource(){modalForm('Đổi tên học liệu',input('Tên','sourceTitle',records[sourceIndex].title),"const v=$('sourceTitle').value.trim();if(v){records[sourceIndex].title=v;saveRecords();closeModal();render()}")}
function tagSource(){modalForm('Gắn thẻ',input('Thẻ, ngăn cách bằng dấu phẩy','sourceTags',(records[sourceIndex].tags||[]).join(', ')),"records[sourceIndex].tags=$('sourceTags').value.split(',').map(x=>x.trim()).filter(Boolean);saveRecords();closeModal();render()")}
function replaceSource(){confirmDemo('Thay phiên bản nguồn?','Tạo phiên bản mô phỏng mới; các kết quả luyện tập cũ vẫn được giữ.',"records[sourceIndex].version=(records[sourceIndex].version||1)+1;records[sourceIndex].status='processing';saveRecords();closeModal();render()")}
function deleteSource(){confirmDemo('Xóa học liệu khỏi bản mẫu?','Nguồn sẽ không còn trong thư viện và lựa chọn nguồn mới.',"records[sourceIndex].deleted=true;saveRecords();closeModal();render()")}
reader=function(){let h=baseReader();const r=records[sourceIndex];const bar=`<div class="actionline reader-extra">${btn('Chọn nguồn','chooseChatSources()',true,'folder')}${btn('Hội thoại',"go('history')",true,'clock')}${btn('Tóm tắt',"askPreset('Tóm tắt nội dung nguồn đã chọn')",true,'spark')}${btn('Đánh dấu trang','bookmarkPage()',true,'note')}${btn('Ghi chú nhanh',"editNotebook(null,'highlight')",true)}${btn('Hoàn thành bài','completeLesson()',true,'check')}</div>`;if(r&&!r.deleted)h=h.replace('<p>Bài giảng Cơ sở dữ liệu.pdf · Nội dung minh họa</p>',`<p>${esc(r.title)} · Trang đọc mẫu, chưa hiển thị file thật</p>`);return h.replace('<div class="reading-switch">',bar+'<p class="source-context">Nguồn hội thoại: '+esc(chatSourceIds.map(id=>records.find(r=>r.id===id&&!r.deleted)?.title).filter(Boolean).join(', ')||'Chưa chọn nguồn')+'</p><div class="reading-switch">')};
function bookmarkPage(){const r=records[sourceIndex]||records[0];persist('lumi-source-page-'+r.id,readerPage);persist('lumi-last-read',{id:r.id,page:readerPage});toast('Đã lưu vị trí trang '+readerPage+' trên trình duyệt.')}
function completeLesson(){const key=selectedCourse+':'+(window.currentLesson||0);if(!completedLessons.includes(key))completedLessons.push(key);persist('lumi-completed',completedLessons);toast('Đã đánh dấu bài học hoàn thành.');}
changePage=function(d){readerPage=Math.min(42,Math.max(1,readerPage+d));const r=records[sourceIndex];if(r)persist('lumi-source-page-'+r.id,readerPage);render()};
function chooseChatSources(){showModal(`<h2 id="modalTitle">Nguồn cho trợ giảng</h2><p>Chọn một hoặc nhiều nguồn đã sẵn sàng.</p><div class="check-list">${records.filter(r=>!r.deleted&&r.status==='ready').map(r=>`<label><input type="checkbox" name="chatSources" value="${r.id}" ${chatSourceIds.includes(r.id)?'checked':''}><span>${esc(r.title)}</span></label>`).join('')}</div><div class="modalactions">${btn('Hủy','closeModal()',true)}${btn('Áp dụng','applyChatSources()')}</div>`)}
function applyChatSources(){const ids=[...document.querySelectorAll('input[name="chatSources"]:checked')].map(x=>x.value);if(!ids.length){toast('Bạn chọn ít nhất một nguồn nhé.');return}chatSourceIds=ids;closeModal();readerTab='chat';readingView='assistant';go('reader');toast('Đã chọn '+ids.length+' nguồn cho hội thoại mẫu.')}
messageHTML=function(m){return `<div class="msg ${m.role}">${m.role==='assistant'?'<span class="label">'+icon('spark')+' LUMI · PHẢN HỒI MẪU</span>':''}${esc(m.text).replace(/\n/g,'<br>')}${m.role==='assistant'?`<div class="actionline compact-actions">${btn('Nguồn · Trang 12',"openCitation()",true,'file')}${btn('Lưu câu trả lời','saveAnswer()',true,'note')}${btn('Báo lỗi',"reportFeedback('answer')",true)}</div>`:''}</div>`};
function openCitation(){readerTab='chat';readingView='document';readerPage=12;go('reader');toast('Đã mở trang 12 của tài liệu mẫu.')}
sendChat=function(value){baseSendChat(value);let q=chatMessages.filter(m=>m.role==='user').at(-1);if(!q)return;if(!activeSession){activeSession=uid();sessions.unshift({id:activeSession,title:q.text.slice(0,55),messages:[],sources:[...chatSourceIds]})}const s=sessions.find(s=>s.id===activeSession);if(s){s.messages=chatMessages.map(m=>({...m}));persist('lumi-chats',sessions)}};
function historyPage(){return head('Hội thoại của bạn','Mở lại một câu hỏi hoặc bắt đầu cuộc trò chuyện mới.',btn('Hỏi mới','newConversation()',false,'plus'))+(sessions.length?`<div class="stack">${sessions.map(s=>`<div class="settingcard"><h2>${esc(s.title)}</h2><p>${s.messages.length} tin nhắn · ${s.sources.length} nguồn</p><div class="actionline">${btn('Mở',`resumeChat('${s.id}')`)}${btn('Đổi tên',`renameChat('${s.id}')`,true)}${btn('Xóa',`deleteChat('${s.id}')`,true)}</div></div>`).join('')}</div>`:empty('Chưa có cuộc trò chuyện được lưu.',btn('Hỏi điều đầu tiên','newConversation()')))+footer()}
function newConversation(){activeSession=null;chatMessages=[];readerTab='chat';readingView='assistant';go('reader')}
function resumeChat(id){let s=sessions.find(x=>x.id===id);if(!s)return;activeSession=id;chatMessages=s.messages.map(m=>({...m}));chatSourceIds=[...s.sources];readerTab='chat';readingView='assistant';go('reader')}
function renameChat(id){const s=sessions.find(x=>x.id===id);modalForm('Đổi tên hội thoại',input('Tên','chatTitle',s.title),`const v=$('chatTitle').value.trim();if(v){sessions.find(x=>x.id==='${id}').title=v;persist('lumi-chats',sessions);closeModal();render()}`)}
function deleteChat(id){confirmDemo('Xóa hội thoại?','Xóa bản hội thoại lưu trên trình duyệt.',`sessions=sessions.filter(x=>x.id!=='${id}');persist('lumi-chats',sessions);closeModal();render()`)}
function reportFeedback(kind){modalForm('Góp ý nội dung',select('Vấn đề','feedbackKind',['Nội dung chưa đúng','Trích dẫn chưa phù hợp','Diễn đạt khó hiểu','Ý kiến khác'])+input('Mô tả','feedbackText'),`feedbacks.push({id:uid(),kind:'${kind}',category:$('feedbackKind').value,text:$('feedbackText').value});persist('lumi-feedback',feedbacks);closeModal();toast('Đã lưu góp ý trong bản mẫu; chưa gửi đi.')`)}
function notesPage(){return head('Ghi chú của mình','Giữ lại điều hữu ích và mở về đúng vị trí học.',btn('Thêm ghi chú','editNotebook()',false,'plus'))+(notebooks.length?`<div class="feature-grid">${notebooks.map(n=>`<article class="settingcard"><span class="badge">${{note:'Ghi chú',highlight:'Đánh dấu',question:'Câu hỏi',saved_answer:'Câu trả lời AI'}[n.kind]||'Ghi chú'} · ${n.videoTime!==undefined?'Video '+timeText(n.videoTime):'Trang '+(n.page||12)}</span><h2 style="margin-top:14px">${esc(n.title)}</h2><p class="note-text">${esc(n.body)}</p><div class="actionline">${btn('Sửa',`editNotebook('${n.id}')`,true)}${btn('Về nguồn',n.videoTime!==undefined?`videoTime=${n.videoTime};go('video')`:`readerPage=${n.page||12};readingView='document';readerTab='chat';go('reader')`,true)}${btn('Tạo thẻ',`editCard(null,'${n.id}')`,true)}${btn('Xóa',`deleteNotebook('${n.id}')`,true)}</div></article>`).join('')}</div>`:empty('Bạn chưa có ghi chú.',btn('Ghi điều đầu tiên','editNotebook()')))+footer()}
function editNotebook(id,kind='note'){let n=notebooks.find(x=>x.id===id)||{title:'',body:'',kind,page:readerPage};modalForm(id?'Sửa ghi chú':'Ghi chú mới',input('Tiêu đề','nbTitle',n.title)+select('Loại ghi chú','nbKind',['Ghi chú','Đánh dấu','Câu hỏi','Câu trả lời AI'],{note:'Ghi chú',highlight:'Đánh dấu',question:'Câu hỏi',saved_answer:'Câu trả lời AI'}[n.kind])+`<label for="nbBody">Nội dung</label><textarea id="nbBody" rows="5" required>${esc(n.body)}</textarea>`, `storeNotebook('${id||''}')`)}
function storeNotebook(id){const title=$('nbTitle').value.trim(),body=$('nbBody').value.trim();if(!title||!body){toast('Bạn nhập tiêu đề và nội dung nhé.');return}let n=notebooks.find(x=>x.id===id),data={title,body,kind:{'Ghi chú':'note','Đánh dấu':'highlight','Câu hỏi':'question','Câu trả lời AI':'saved_answer'}[$('nbKind').value],page:readerPage};if(n)Object.assign(n,data);else notebooks.unshift({id:uid(),...data});saveAllNotes();closeModal();go('notes')}
function deleteNotebook(id){confirmDemo('Xóa ghi chú?','Xóa ghi chú này trên trình duyệt.',`notebooks=notebooks.filter(x=>x.id!=='${id}');saveAllNotes();closeModal();render()`)}
saveAnswer=function(){let m=chatMessages.filter(m=>m.role==='assistant').at(-1);if(!m)return;notebooks.unshift({id:uid(),title:'Câu trả lời từ Lumi',body:m.text,kind:'saved_answer',page:12});saveAllNotes();note+='\n\n'+m.text;persist('sf-note',note);toast('Đã lưu vào Ghi chú → Câu trả lời AI.')};
saveNote=function(){note=$('noteEditor').value;persist('sf-note',note);let n=notebooks.find(n=>n.id==='note0');if(n)n.body=note;else notebooks.unshift({id:'note0',title:'Ghi chú trong bài',body:note,kind:'note',page:readerPage});saveAllNotes();toast('Đã lưu ghi chú trên trình duyệt.')};
course=function(){let c=[...courses,...extraCourses][selectedCourse]||courses[0],lessons=drafts[selectedCourse]||['Tổng quan môn học','Các khái niệm nền tảng','Khóa và ràng buộc','Ứng dụng và luyện tập'];return head(esc(c.title),'Khóa học cá nhân · Bạn tự chọn thứ tự và nhịp học.',btn('Quản lý','manageCourse()',true))+`<div class="actionline">${btn('Thêm nguồn','linkCourseSources()',true,'folder')}${btn('Gợi ý đề cương','editCurriculum()',true,'spark')}${btn('Luyện tập','quizSetup()',true,'quiz')}${btn('Ghi chú',"go('notes')",true,'note')}</div><section class="settingcard" style="margin:18px 0"><h2>Đề cương bài học</h2><p>Đề cương do bạn kiểm tra và chỉnh sửa trước khi áp dụng.</p>${btn('Chỉnh đề cương','editCurriculum()',true)}</section>${lessons.map((t,i)=>`<button class="lessonrow" onclick="window.currentLesson=${i};readerTab='chat';readingView='document';go('reader')"><span class="lessonnum">${completedLessons.includes(selectedCourse+':'+i)?icon('check'):String(i+1).padStart(2,'0')}</span><span><h3>${esc(t)}</h3><p>${completedLessons.includes(selectedCourse+':'+i)?'Đã hoàn thành':'Chưa hoàn thành'} · Tài liệu và ví dụ minh họa</p></span>${icon('chevron')}</button>`).join('')}<p class="setting-note">Nguồn đã liên kết: ${esc((saved('lumi-course-sources-'+selectedCourse,[]).map(id=>records.find(r=>r.id===id)?.title).filter(Boolean).join(', '))||'Chưa chọn — bài học đang dùng nguồn mẫu')}</p>`+footer()};
function editCurriculum(){let list=drafts[selectedCourse]||['Tổng quan môn học','Các khái niệm nền tảng','Khóa và ràng buộc','Ứng dụng và luyện tập'];modalForm('Đề cương dự thảo',`<p>Đề xuất mẫu. Mỗi dòng là một bài; sửa tên, thêm, xóa hoặc đổi thứ tự trước khi áp dụng.</p><label for="curriculumText">Các bài học</label><textarea id="curriculumText" rows="7">${esc(list.join('\n'))}</textarea>`,"applyCurriculum()",'Áp dụng đề cương')}
function applyCurriculum(){const items=$('curriculumText').value.split('\n').map(s=>s.trim()).filter(Boolean);if(!items.length){toast('Cần ít nhất một bài học.');return}drafts[selectedCourse]=items;persist('lumi-curriculum',drafts);closeModal();go('course')}
function linkCourseSources(){showModal(`<h2 id="modalTitle">Liên kết nguồn vào khóa</h2><div class="check-list">${records.filter(r=>!r.deleted).map(r=>`<label><input name="courseSources" type="checkbox" value="${r.id}" ${saved('lumi-course-sources-'+selectedCourse,[]).includes(r.id)?'checked':''}>${esc(r.title)}</label>`).join('')}</div><div class="modalactions">${btn('Hủy','closeModal()',true)}${btn('Liên kết',"persist('lumi-course-sources-'+selectedCourse,[...document.querySelectorAll('input[name=courseSources]:checked')].map(x=>x.value));closeModal();render()")}</div>`)}
function manageCourse(){const c=[...courses,...extraCourses][selectedCourse];modalForm('Sửa khóa học',input('Tên khóa học','editCourseName',c.title)+input('Mô tả / mục tiêu','editCourseGoal',c.subtitle),"const c=[...courses,...extraCourses][selectedCourse];const v=$('editCourseName').value.trim();if(v){c.title=v;c.cover=v;c.subtitle=$('editCourseGoal').value;persist('sf-courses',extraCourses);persist('lumi-default-courses',courses);closeModal();render()}");$('overlay').querySelector('.modal').insertAdjacentHTML('beforeend',`<div class="actionline">${btn('Lưu trữ khóa học','archiveCourse()',true)}</div>`)}
function archiveCourse(){const c=[...courses,...extraCourses][selectedCourse];c.archived=!c.archived;persist('sf-courses',extraCourses);persist('lumi-default-courses',courses);closeModal();tab='courses';go('library');toast(c.archived?'Đã lưu trữ khóa học. Có thể khôi phục trong Quản lý.':'Đã khôi phục khóa học.')}
const baseCourseCard=courseCard;courseCard=function(c,i){return baseCourseCard(c,i).replace('<h3>',`<h3>${c.archived?'[Lưu trữ] ':''}`)};
function quizSetup(){modalForm('Tạo bài luyện',select('Phạm vi','quizScope',['Khóa và ràng buộc','Bài học hiện tại','Nguồn đã chọn'])+select('Mức độ','quizLevel',['Cơ bản','Vận dụng','Kết hợp'])+select('Chế độ','quizStyle',['Luyện tập — xem lời giải từng câu','Tự kiểm tra — xem kết quả sau cùng'])+`<p>Bản mẫu có 3 câu hỏi cố định để bạn thử đầy đủ luồng làm bài.</p>`,"quizMode=$('quizStyle').value.startsWith('Tự')?'test':'practice';closeModal();quizPicked=[];startQuiz()",'Bắt đầu 3 câu')}
quiz=function(){if(quizIndex>=questions.length)return quizResults();if(quizMode==='practice')return baseQuiz().replace("onclick=\"toast('Nguồn minh họa: Bài giảng CSDL, trang 12')\"","onclick=\"openCitation()\"");const q=questions[quizIndex];return head('Tự kiểm tra',`Câu ${quizIndex+1} / ${questions.length} · Không giới hạn thời gian`)+`<section class="quizcard"><h2>${esc(q.q)}</h2>${q.a.map((a,i)=>`<button class="answer ${answer===i?'selected':''}" onclick="answer=${i};render()"><span>${String.fromCharCode(65+i)}</span>${esc(a)}</button>`).join('')}<div class="quizactions">${btn('Để sau',"go('hub')",true)}${btn(quizIndex===2?'Nộp bài':'Câu tiếp theo','nextTestQuestion()')}</div></section>`};
function nextTestQuestion(){if(answer===null){toast('Bạn chọn một đáp án trước nhé.');return}quizPicked[quizIndex]=answer;if(answer===questions[quizIndex].correct)score++;quizIndex++;answer=null;if(quizIndex>=questions.length)saveAttempt();render()}
checkQuiz=function(){if(!checked&&answer!==null)quizPicked[quizIndex]=answer;const final=checked&&quizIndex===questions.length-1;baseCheckQuiz();if(final)saveAttempt()};
function saveAttempt(){attempts.unshift({id:uid(),score,total:questions.length,picks:[...quizPicked],when:new Date().toLocaleString('vi-VN')});persist('lumi-attempts',attempts)}
function quizResults(){return head('Bạn đã hoàn thành',`${score} / ${questions.length} câu đúng · Kết quả từ bài luyện mẫu`)+`<section class="quizcard"><h2>Cùng nhìn lại từng câu</h2>${questions.map((q,i)=>`<div class="result-item"><span class="badge">Câu ${i+1} · ${quizPicked[i]===q.correct?'Đúng':'Cần xem lại'}</span><h3>${esc(q.q)}</h3><p>Đáp án: ${esc(q.a[q.correct])}</p><p>${esc(q.explain)}</p><div class="actionline">${btn('Lưu để ôn',`quizIndex=${i};saveReview();quizIndex=questions.length`,true)}${btn('Về nguồn','openCitation()',true)}</div></div>`).join('')}<div class="actionline">${btn('Sổ ôn tập',"go('review')")}${btn('Luyện lại','quizSetup()',true)}${btn('Tiến độ',"go('stats')",true)}</div></section>`+footer()}
function reviewPage(){const ids=saved('sf-review',[]);return head('Sổ ôn tập','Chọn lưu câu cần xem lại. Bạn tự quyết định khi nào ôn.')+(ids.length?`<div class="stack">${ids.filter(i=>questions[i]).map(i=>`<section class="settingcard"><span class="badge">Khóa và ràng buộc · Câu ${i+1}</span><h2 style="margin-top:12px">${esc(questions[i].q)}</h2><p>${esc(questions[i].explain)}</p><div class="actionline">${btn('Luyện từ câu này',`quizMode='practice';quizPicked=[];quizIndex=${i};answer=null;checked=false;score=0;go('quiz')`)}${btn('Xem nguồn','openCitation()',true)}${btn('Đã hiểu',`persist('sf-review',saved('sf-review',[]).filter(x=>x!==${i}));render()`,true)}</div></section>`).join('')}</div>`:empty('Chưa có câu cần ôn. Bạn có thể lưu câu sau khi làm bài.',btn('Thử bài luyện','quizSetup()')))+footer()}
function flashcardsPage(){const card=cardDeck[flashIndex%Math.max(1,cardDeck.length)];return head('Thẻ ghi nhớ','Ôn tự do bất kỳ lúc nào; lịch ôn là tùy chọn.',btn('Thêm thẻ','editCard()',false,'plus'))+`<div class="actionline">${btn('Tạo bộ thẻ mẫu','generateCards()',true,'spark')}${btn('Tùy chọn lịch ôn',"go('personal')",true)}</div>`+(card?`<section class="flash-panel"><div class="sectiontitle"><span class="badge">Thẻ ${flashIndex%cardDeck.length+1} / ${cardDeck.length}</span><span>${esc(card.due||'Ôn tự do')}</span></div><button class="flash-face" onclick="flipped=!flipped;render()"><span class="eyebrow">${flipped?'CÂU TRẢ LỜI':'TỰ NHỚ TRƯỚC KHI LẬT'}</span><h2>${esc(flipped?card.a:card.q)}</h2><small>${flipped?'Bấm để trở lại câu hỏi':'Bấm để lật thẻ'}</small></button>${flipped?`<p class="setting-note">Bạn nhớ nội dung này thế nào?</p><div class="card-ratings">${[['Chưa nhớ',1],['Hơi khó',2],['Nhớ được',3],['Rất dễ',4]].map(([t,v])=>btn(t,`rateCard(${v})`,true)).join('')}</div>`:btn('Xem câu trả lời','flipped=true;render()')}<div class="actionline">${btn('Thẻ trước','flashIndex=(flashIndex+cardDeck.length-1)%cardDeck.length;flipped=false;render()',true)}${btn('Thẻ sau','flashIndex=(flashIndex+1)%cardDeck.length;flipped=false;render()',true)}${btn('Sửa',`editCard('${card.id}')`,true)}${btn('Xóa',`deleteCard('${card.id}')`,true)}</div></section>`:empty('Chưa có thẻ ghi nhớ.',btn('Tạo thẻ đầu tiên','editCard()')))+footer()}
function editCard(id,noteId){let c=cardDeck.find(c=>c.id===id),n=notebooks.find(n=>n.id===noteId);c=c||{q:n?n.title:'',a:n?n.body:''};modalForm(id?'Sửa thẻ':'Tạo thẻ ghi nhớ',input('Câu hỏi / mặt trước','cardQ',c.q)+`<label for="cardA">Câu trả lời / mặt sau</label><textarea id="cardA" rows="5" required>${esc(c.a)}</textarea>`,`storeCard('${id||''}')`)}
function storeCard(id){let q=$('cardQ').value.trim(),a=$('cardA').value.trim();if(!q||!a){toast('Bạn nhập cả hai mặt thẻ nhé.');return}let c=cardDeck.find(x=>x.id===id);if(c)Object.assign(c,{q,a});else cardDeck.push({id:uid(),q,a,due:'Ôn tự do'});persist('lumi-cards',cardDeck);closeModal();flashIndex=cardDeck.length-1;flipped=false;go('flashcards')}
function deleteCard(id){confirmDemo('Xóa thẻ này?','Chỉ xóa thẻ trong bản mẫu trên trình duyệt.',`cardDeck=cardDeck.filter(c=>c.id!=='${id}');persist('lumi-cards',cardDeck);flashIndex=0;flipped=false;closeModal();render()`)}
function generateCards(){confirmDemo('Thêm bộ thẻ từ bài học?','Bản mẫu sẽ thêm 2 thẻ ví dụ. Khi có AI thật, nội dung sẽ được sinh từ nguồn bạn chọn.',"cardDeck.push({id:uid(),q:'Toàn vẹn tham chiếu là gì?',a:'Giá trị khóa ngoại khác NULL phải tham chiếu đến giá trị tồn tại trong bảng liên quan.',due:'Ôn tự do'},{id:uid(),q:'Khóa chính có thể gồm nhiều cột không?',a:'Có, đó là khóa chính ghép.',due:'Ôn tự do'});persist('lumi-cards',cardDeck);closeModal();go('flashcards')")}
function rateCard(rating){let c=cardDeck[flashIndex%cardDeck.length];c.rating=rating;c.due=tools.flashcards?['Ôn lại hôm nay','Ngày mai','Sau 3 ngày','Sau 7 ngày'][rating-1]:'Ôn tự do';persist('lumi-cards',cardDeck);persist('lumi-card-reviews',saved('lumi-card-reviews',0)+1);flashIndex=(flashIndex+1)%cardDeck.length;flipped=false;render();toast(tools.flashcards?'Đã cập nhật lịch ôn mô phỏng.':'Đã lưu mức nhớ. Lịch ôn đang tắt.')}
function plannerPage(){let goal=saved('lumi-week-goal','Hiểu rõ khóa chính và khóa ngoại');return head('Kế hoạch nhẹ nhàng','Tự chọn việc cần làm, không bắt buộc deadline.',btn('Thêm việc','editPlan()',false,'plus'))+`<section class="settingcard"><span class="badge">Mục tiêu của tuần</span><h2 style="margin-top:14px">${esc(goal)}</h2>${btn('Sửa mục tiêu','editGoal()',true)}<p>${plans.filter(p=>p.done).length} / ${plans.length} việc đã hoàn thành</p></section><div class="stack" style="margin-top:18px">${plans.map(p=>`<div class="plan-row settingcard"><button class="task-check ${p.done?'done':''}" aria-label="${p.done?'Bỏ hoàn thành':'Hoàn thành'} ${esc(p.title)}" onclick="togglePlan('${p.id}')">${p.done?icon('check'):''}</button><div class="plan-info"><h3>${esc(p.title)}</h3><p>${esc(p.day)} · ${p.minutes} phút</p></div><div class="actionline">${btn('Sửa',`editPlan('${p.id}')`,true)}${btn('Xóa',`deletePlan('${p.id}')`,true)}</div></div>`).join('')||empty('Bạn chưa đặt việc nào.')}</div><section class="settingcard" style="margin-top:20px"><div class="sectiontitle"><h2>Nhắc học tùy chọn</h2>${btn('Thêm nhắc','editReminder()',true,'plus')}</div><p>Chỉ hiển thị lịch trong bản mẫu; chưa gửi thông báo thiết bị.</p>${reminders.map(r=>`<div class="reminder-row"><span>${esc(r.title)}<small>${esc(r.time)} · ${esc(r.days)} · Asia/Bangkok</small></span><button class="toggle ${r.enabled?'on':''}" role="switch" aria-checked="${r.enabled}" aria-label="Bật nhắc ${esc(r.title)}" onclick="toggleReminder('${r.id}')"><span></span></button>${btn('Xóa',`reminders=reminders.filter(r=>r.id!=='${r.id}');persist('lumi-reminders',reminders);render()`,true)}</div>`).join('')||'<p>Chưa có lịch nhắc.</p>'}</section>`+footer()}
function editGoal(){modalForm('Mục tiêu tuần này',input('Điều bạn muốn hiểu','weekGoal',saved('lumi-week-goal','')),"persist('lumi-week-goal',$('weekGoal').value.trim());closeModal();render()")}
function editPlan(id){let p=plans.find(x=>x.id===id)||{title:'',day:'Thứ hai',minutes:20};modalForm(id?'Sửa việc học':'Thêm việc học',input('Tên việc','planTitle',p.title)+select('Ngày dự kiến','planDay',['Thứ hai','Thứ ba','Thứ tư','Thứ năm','Thứ sáu','Thứ bảy','Chủ nhật','Khi rảnh'],p.day)+input('Thời gian dự kiến (phút)','planMinutes',p.minutes,'number'),`storePlan('${id||''}')`)}
function storePlan(id){let title=$('planTitle').value.trim(),minutes=Number($('planMinutes').value);if(!title||minutes<1||minutes>480){toast('Nhập tên việc và thời lượng từ 1–480 phút.');return}let p=plans.find(x=>x.id===id),data={title,minutes,day:$('planDay').value};if(p)Object.assign(p,data);else plans.push({id:uid(),done:false,...data});persist('lumi-plans',plans);closeModal();go('planner')}
function togglePlan(id){let p=plans.find(x=>x.id===id);p.done=!p.done;persist('lumi-plans',plans);render()}
function deletePlan(id){confirmDemo('Xóa việc này?','Mục tiêu tuần và những việc khác vẫn được giữ.',`plans=plans.filter(p=>p.id!=='${id}');persist('lumi-plans',plans);closeModal();render()`)}
function editReminder(){modalForm('Nhắc học nhẹ nhàng',input('Nội dung','reminderTitle','Dành 15 phút ôn bài')+input('Giờ nhắc','reminderTime','20:00','time')+select('Ngày nhắc','reminderDays',['Hằng ngày','Thứ hai, tư, sáu','Cuối tuần']),"const t=$('reminderTitle').value.trim();if(t&&$('reminderTime').value){reminders.push({id:uid(),title:t,time:$('reminderTime').value,days:$('reminderDays').value,enabled:true});persist('lumi-reminders',reminders);closeModal();go('planner')}")}
function toggleReminder(id){let r=reminders.find(x=>x.id===id);r.enabled=!r.enabled;persist('lumi-reminders',reminders);render()}
function focusPage(){return head('Một khoảng để tập trung','Không cần vội. Bạn có thể dừng bất kỳ lúc nào.')+`<section class="focus-card settingcard"><div class="eyebrow">PHIÊN HỌC CỦA BẠN</div><div id="focusClock" class="focus-clock">25:00</div><p id="focusState">${focusRunning?'Đang tập trung':'Sẵn sàng khi bạn muốn'}</p><div class="actionline centered">${[15,25,45].map(n=>btn(n+' phút',`setFocus(${n})`,true)).join('')}</div><div class="actionline centered">${btn(focusRunning?'Tạm dừng':'Bắt đầu','toggleFocus()',false,'play')}${btn('Đặt lại','resetFocus()',true)}${btn('Kết thúc & lưu','finishFocus()',true,'check')}</div><p>Đồng hồ chạy trong trình duyệt, không cần cấp quyền thông báo.</p></section>`+footer()}
function paintTimer(){let el=$('focusClock');if(el)el.textContent=String(Math.floor(focusSeconds/60)).padStart(2,'0')+':'+String(focusSeconds%60).padStart(2,'0')}
function setFocus(n){if(focusTimer)clearInterval(focusTimer);focusRunning=false;focusSeconds=n*60;render()}
function toggleFocus(){if(focusRunning){focusSeconds=Math.max(0,Math.ceil((focusDeadline-Date.now())/1000));focusRunning=false;clearInterval(focusTimer)}else{focusDeadline=Date.now()+focusSeconds*1000;focusRunning=true;focusTimer=setInterval(()=>{focusSeconds=Math.max(0,Math.ceil((focusDeadline-Date.now())/1000));if(focusSeconds===0){focusRunning=false;clearInterval(focusTimer);toast('Phiên tập trung đã kết thúc. Bạn có thể lưu phiên học.')}if(page==='focus')paintTimer()},500)}render()}
function resetFocus(){setFocus(25)}
function finishFocus(){if(focusTimer)clearInterval(focusTimer);focusRunning=false;let log=saved('lumi-focus-sessions',[]);log.unshift({id:uid(),when:new Date().toLocaleString('vi-VN'),remaining:focusSeconds});persist('lumi-focus-sessions',log);focusSeconds=25*60;go('stats');toast('Đã lưu phiên tập trung trên trình duyệt.')}
function statsPage(){const logs=saved('lumi-focus-sessions',[]),reviews=saved('lumi-card-reviews',0);return head('Hành trình học của bạn','Số liệu từ thao tác bạn đã thực hiện trong bản giao diện.')+`<div class="stats-grid">${[[completedLessons.length,'Bài đánh dấu hoàn thành'],[attempts.length,'Bài luyện đã nộp'],[reviews,'Lượt ôn thẻ'],[logs.length,'Phiên tập trung']].map(([n,t])=>`<div class="settingcard stat"><strong>${n}</strong><span>${t}</span></div>`).join('')}</div><div class="two-col" style="margin-top:22px"><section class="settingcard"><h2>Lịch sử luyện tập</h2>${attempts.map(a=>`<div class="result-item"><strong>${a.score} / ${a.total} câu đúng</strong><p>${esc(a.when)}</p>${btn('Xem lại',`showAttempt('${a.id}')`,true)}</div>`).join('')||'<p>Chưa có bài luyện được nộp.</p>'}${btn('Luyện tập','quizSetup()',true)}</section><section class="settingcard"><h2>Phiên tập trung</h2>${logs.map(l=>`<p>${esc(l.when)} · Đã lưu</p>`).join('')||'<p>Chưa có phiên tập trung.</p>'}${btn('Bắt đầu một phiên',"go('focus')",true)}<h2 style="margin-top:25px">Gợi ý tiếp theo</h2><p>${saved('sf-review',[]).length?'Bạn có một vài câu đã lưu để ôn.':'Bạn có thể xem tiếp học liệu hoặc thử một bài luyện ngắn.'}</p>${btn('Mở sổ ôn tập',"go('review')",true)}</section></div>`+footer()}
function showAttempt(id){let a=attempts.find(x=>x.id===id);quizPicked=[...a.picks];score=a.score;quizIndex=questions.length;go('quiz')}
const terms=[['Khóa chính','Một hoặc nhiều thuộc tính xác định duy nhất mỗi bản ghi. Không chứa NULL.'],['Khóa ngoại','Thuộc tính tham chiếu tới khóa phù hợp trong bảng liên quan.'],['Toàn vẹn tham chiếu','Bảo đảm liên kết giữa các bảng giữ được tính nhất quán.'],['Mô hình quan hệ','Biểu diễn dữ liệu bằng các bảng, hàng và cột.']];
let termSearch='';
function glossaryPage(){return head('Thuật ngữ dễ hiểu','Các khái niệm mẫu kèm vị trí trong học liệu.')+`<form class="searchbox glossary-search" onsubmit="event.preventDefault();termSearch=$('termSearch').value;render()">${icon('search')}<input id="termSearch" aria-label="Tìm thuật ngữ" placeholder="Tìm thuật ngữ..." value="${esc(termSearch)}"><button class="textbtn">Tìm</button></form><div class="stack">${terms.filter(([t])=>t.toLowerCase().includes(termSearch.toLowerCase())).map(([t,d])=>`<section class="settingcard"><h2>${t}</h2><p>${d}</p><div class="actionline">${btn('Nguồn · Trang 12','openCitation()',true,'file')}${btn('Hỏi thêm',`askPreset('Giải thích ${t}')`,true)}${btn('Lưu khái niệm',`saveTerm('${t}')`,true)}</div></section>`).join('')||empty('Không tìm thấy thuật ngữ.')}</div>`+footer()}
function saveTerm(t){const term=terms.find(([x])=>x===t);notebooks.unshift({id:uid(),title:term[0],body:term[1],kind:'note',page:12});saveAllNotes();toast('Đã lưu khái niệm vào ghi chú.')}
function outlinesPage(){return head('Đề cương ôn tập','Tóm lược những ý bạn muốn tự kiểm tra.',btn('Tạo đề cương mẫu','newOutline()',false,'plus'))+`<div class="stack">${outlines.map(o=>`<section class="settingcard"><h2>${esc(o.title)}</h2><ul class="outline-list">${o.items.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><div class="actionline">${btn('Chỉnh sửa',`editOutline('${o.id}')`,true)}${btn('Bắt đầu ôn','activeRecall()',true)}${btn('Xóa',`deleteOutline('${o.id}')`,true)}</div></section>`).join('')||empty('Chưa có đề cương.')}</div>`+footer()}
function newOutline(){outlines.unshift({id:uid(),title:'Đề cương ôn tập mới',items:['Khái niệm chính trong bài','Một ví dụ vận dụng','Câu hỏi mình chưa hiểu']});persist('lumi-outlines',outlines);go('outlines')}
function editOutline(id){let o=outlines.find(x=>x.id===id);modalForm('Sửa đề cương',input('Tiêu đề','outlineTitle',o.title)+`<label for="outlineText">Các ý cần ôn (mỗi dòng một ý)</label><textarea id="outlineText" rows="6">${esc(o.items.join('\n'))}</textarea>`,`let o=outlines.find(x=>x.id==='${id}');o.title=$('outlineTitle').value;o.items=$('outlineText').value.split('\\n').filter(x=>x.trim());persist('lumi-outlines',outlines);closeModal();render()`)}
function deleteOutline(id){confirmDemo('Xóa đề cương?','Ghi chú và tài liệu liên quan vẫn được giữ.',`outlines=outlines.filter(x=>x.id!=='${id}');persist('lumi-outlines',outlines);closeModal();render()`)}
function activeRecall(){modalForm('Tự giải thích một chút',`<p>Hãy giải thích khóa ngoại bằng một ví dụ theo cách bạn hiểu.</p><label for="recallText">Câu trả lời của bạn</label><textarea id="recallText" rows="6" required></textarea>`,"recallFeedback()",'Xem phản hồi mẫu')}
function recallFeedback(){const text=$('recallText').value.trim();if(!text)return;showModal(`<h2 id="modalTitle">Cùng xem lại cách hiểu</h2><p class="note-text">${esc(text)}</p><div class="feedback"><strong>Phản hồi minh họa, chưa chấm bằng AI</strong><p>Một lời giải thích rõ nên có: bảng chứa khóa ngoại, bảng được tham chiếu và một ví dụ giá trị liên kết giữa hai bảng.</p></div><div class="modalactions">${btn('Xem nguồn','closeModal();openCitation()',true)}${btn('Thử lại','activeRecall()')}</div>`)}
function authPage(){const isLogin=authMode==='login',reset=authMode==='reset';return head('Tài khoản Lumi','Thử luồng tài khoản bằng dữ liệu mẫu. Không gửi hoặc lưu mật khẩu.')+`<div class="auth-wrap settingcard"><span class="brandmark">${icon('leaf')}</span><h2>${reset?'Khôi phục mật khẩu':isLogin?'Chào mừng bạn trở lại':'Tạo không gian học của bạn'}</h2><form class="lumi-form" onsubmit="event.preventDefault();submitAuth()">${!isLogin&&!reset?input('Tên hiển thị','authName',userProfile.name):''}${input('Email','authEmail',userProfile.email,'email')}${reset?'':input('Mật khẩu (chỉ thử giao diện)','authPassword','','password')}<p class="prototype-banner">Đăng nhập mô phỏng · Không sử dụng mật khẩu tài khoản thật.</p><button class="btn" type="submit">${reset?'Gửi yêu cầu mẫu':isLogin?'Vào Lumi':'Tạo tài khoản mẫu'}</button></form><div class="actionline centered">${btn(isLogin?'Đăng ký':'Đăng nhập',`authMode='${isLogin?'signup':'login'}';render()`,true)}${btn('Quên mật khẩu',"authMode='reset';render()",true)}</div>${btn('Tiếp tục xem bản mẫu',"go('home')",true)}</div>`+footer()}
function submitAuth(){const email=$('authEmail').value.trim();if(!email){toast('Bạn nhập email nhé.');return}if(authMode==='reset'){showModal('<h2 id="modalTitle">Yêu cầu mẫu đã hoàn tất</h2><p>Nếu triển khai thật, hướng dẫn khôi phục sẽ được gửi tới email phù hợp. Bản này không gửi email.</p><div class="modalactions">'+btn('Về đăng nhập',"closeModal();authMode='login';go('auth')")+'</div>');return}if($('authPassword').value.length<6){toast('Nhập ít nhất 6 ký tự để thử luồng.');return}if(authMode==='signup')userProfile.name=$('authName').value.trim()||'Bạn';userProfile.email=email;persist('lumi-profile',userProfile);go('home');toast('Đã vào tài khoản mẫu. Chưa xác thực với máy chủ.')}
function editProfile(){modalForm('Hồ sơ học tập',input('Tên hiển thị','profileName',userProfile.name)+input('Email','profileEmail',userProfile.email,'email')+select('Trình độ tự khai báo','profileLevel',['Sinh viên năm 1','Sinh viên năm 2','Sinh viên năm 3','Sinh viên năm 4','Người tự học'],userProfile.level)+input('Mục tiêu học tập','profileGoal',userProfile.goal)+select('Cách giải thích bạn thích','profileStyle',['Giải thích dễ hiểu','Ngắn gọn, đi thẳng ý','Nhiều ví dụ cụ thể'],userProfile.style),"const name=$('profileName').value.trim();if(name){Object.assign(userProfile,{name,email:$('profileEmail').value,level:$('profileLevel').value,goal:$('profileGoal').value,style:$('profileStyle').value});persist('lumi-profile',userProfile);closeModal();render()}")}
const originalSettingsDetail=settingsDetail;
settingsDetail=function(kind){if(kind==='account'){editProfile();return}if(kind==='plan'){quotaDialog();return}if(kind==='privacy'){privacyDialog();return}originalSettingsDetail(kind)};
personal=function(){let h=basePersonal().replace('Thức Tri',esc(userProfile.name)).replace('Sinh viên · Không gian cá nhân',esc(userProfile.level)+' · Không gian cá nhân');const extra=`<section class="settings-section"><h2 class="group-label">Tài khoản & hoạt động</h2><div class="settings-group">${prefRow('user','#408b71','Hồ sơ học tập','Trình độ, mục tiêu, cách giải thích','editProfile()')}${prefRow('clock','#7683b4','Thiết bị & phiên đăng nhập','Xem phiên mẫu và đăng xuất','devicesDialog()')}${prefRow('book','#40879a','Hạn mức & lưu trữ','Theo dõi mức sử dụng minh họa','quotaDialog()')}${prefRow('note','#ba8b5c','Tiến độ học tập','Lịch sử bài luyện và phiên học',"go('stats')")}${prefRow('help','#8c74ab','Góp ý đã lưu','Xem nội dung góp ý trong bản mẫu','feedbackDialog()')}</div></section>`;return h.replace('<div class="settings-foot">',extra+'<div class="settings-foot">')};
function quotaDialog(){showModal(`<h2 id="modalTitle">Hạn mức & lưu trữ</h2><p>Số liệu minh họa để xem thiết kế, chưa phản ánh tài khoản thật.</p>${[['Lượt trợ giảng AI','12 / 100 lượt',12],['Dung lượng nguồn','48 / 500 MB',10],['Thời lượng video','18 / 120 phút',15]].map(([t,v,p])=>`<div class="result-item"><div class="sectiontitle"><strong>${t}</strong><span>${v}</span></div><div class="progressline"><span style="width:${p}%"></span></div></div>`).join('')}<div class="modalactions">${btn('Xong','closeModal()')}</div>`)}
function devicesDialog(){showModal(`<h2 id="modalTitle">Thiết bị & phiên đăng nhập</h2><div class="result-item"><strong>Trình duyệt hiện tại</strong><p>Phiên minh họa · Không đồng bộ máy chủ</p></div><p>Vị trí đọc và dữ liệu mẫu được nhớ trên trình duyệt này.</p><div class="modalactions">${btn('Đóng','closeModal()',true)}${btn('Đăng xuất mẫu',"closeModal();authMode='login';go('auth')")}</div>`)}
function privacyDialog(){showModal(`<h2 id="modalTitle">Dữ liệu của bạn</h2><p>Dữ liệu bạn tạo trong bản mẫu chỉ lưu trong trình duyệt này. Bạn có thể xuất ghi chú và dữ liệu mẫu.</p><div class="actionline">${btn('Xuất ghi chú','exportNotes()',true)}${btn('Xuất dữ liệu mẫu','exportPrototypeData()',true)}</div><p>Xóa dữ liệu mẫu sẽ xóa ghi chú, thẻ, lịch và hội thoại bạn đã tạo ở đây.</p><div class="modalactions">${btn('Đóng','closeModal()',true)}${btn('Xóa dữ liệu mẫu','confirmClearPrototype()')}</div>`)}
exportNotes=function(){let text=notebooks.map(n=>n.title+'\n'+n.body).join('\n\n---\n\n');let url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));let a=document.createElement('a');a.href=url;a.download='Lumi-ghi-chu.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
function exportPrototypeData(){let data={profile:userProfile,sources:records,notes:notebooks,chats:sessions,cards:cardDeck,plans,reminders,attempts},url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));let a=document.createElement('a');a.href=url;a.download='Lumi-du-lieu-mau.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function confirmClearPrototype(){confirmDemo('Xóa dữ liệu bản mẫu?','Thao tác này chỉ xóa dữ liệu Lumi và StudyFlow lưu trong trình duyệt. Bạn có thể xuất dữ liệu trước.',"for(const key of Object.keys(localStorage))if(key.startsWith('lumi-')||key.startsWith('sf-'))localStorage.removeItem(key);location.reload()")}
function feedbackDialog(){showModal(`<h2 id="modalTitle">Góp ý đã lưu</h2><p>Góp ý chỉ được lưu tại đây, chưa gửi đến ai.</p>${feedbacks.map(f=>`<div class="result-item"><strong>${esc(f.category)}</strong><p>${esc(f.text)||'Không có mô tả thêm'}</p></div>`).join('')||'<p>Chưa có góp ý. Bạn có thể chọn Báo lỗi trong câu trả lời AI.</p>'}<div class="modalactions">${btn('Xong','closeModal()')}</div>`)}
const transcript=[{s:0,t:'Trong bài này, chúng ta tìm hiểu mô hình mạng OSI.'},{s:65,t:'Mô hình OSI chia hoạt động truyền thông thành bảy tầng.'},{s:125,t:'Tầng mạng chịu trách nhiệm định tuyến và địa chỉ logic.'},{s:185,t:'Tầng giao vận hỗ trợ truyền dữ liệu giữa các ứng dụng.'}];
function timeText(s){return Math.floor(s/60)+':'+String(s%60).padStart(2,'0')}
function videoPage(){return head('Video & transcript','Mô hình OSI · Trình phát và nội dung mô phỏng')+`<div class="video-layout"><section><div class="video-stage"><span class="badge">VIDEO MẪU · KHÔNG PHÁT FILE THẬT</span><span class="video-symbol">${icon('play')}</span><h2>Mô hình OSI</h2><p>Bảy tầng kết nối thế giới</p></div><div class="video-controls"><button class="btn" onclick="videoPlaying=!videoPlaying;render()">${videoPlaying?'Tạm dừng':'Phát mô phỏng'}</button><input aria-label="Vị trí video mẫu" type="range" min="0" max="240" value="${videoTime}" oninput="videoTime=Number(this.value);$('videoPosition').textContent=timeText(videoTime)"><span id="videoPosition">${timeText(videoTime)}</span><span>/ 4:00</span></div><div class="actionline">${btn('Ghi chú tại mốc này',"editVideoNote()",true,'note')}${btn('Hỏi về đoạn này',"askPreset('Giải thích tầng mạng trong mô hình OSI')",true,'spark')}${btn('Lưu vị trí','persistVideoPosition()',true)}</div><section class="settingcard" style="margin-top:16px"><h2>Tóm tắt nội dung</h2><p>Video mẫu giới thiệu các tầng của OSI, đặc biệt tầng mạng và tầng giao vận. Nội dung này chỉ là mẫu để thử điều hướng.</p></section></section><section class="settingcard transcript"><h2>Transcript theo mốc</h2><p>Chọn dòng để chuyển tới vị trí tương ứng.</p>${transcript.map((x,i)=>`<button class="transcript-line ${videoTime>=x.s&&(i===transcript.length-1||videoTime<transcript[i+1].s)?'active':''}" onclick="videoTime=${x.s};render()"><span>${timeText(x.s)}</span><p>${x.t}</p></button>`).join('')}</section></div>`+footer()}
function editVideoNote(){modalForm('Ghi chú tại '+timeText(videoTime),input('Tiêu đề','videoNoteTitle','Ghi chú video '+timeText(videoTime))+`<label for="videoNoteText">Nội dung</label><textarea id="videoNoteText" rows="4" required></textarea>`,"notebooks.unshift({id:uid(),title:$('videoNoteTitle').value,body:'['+timeText(videoTime)+'] '+$('videoNoteText').value,kind:'note',videoTime});saveAllNotes();closeModal();toast('Đã lưu ghi chú theo mốc video.')")}
function persistVideoPosition(){persist('lumi-video-position',videoTime);toast('Đã lưu vị trí video '+timeText(videoTime)+'.')}
setInterval(()=>{if(videoPlaying){videoTime=Math.min(240,videoTime+1);if(videoTime===240)videoPlaying=false;if(page==='video')render()}},1000);
// Restore editable sample courses while keeping prior notes and preferences.
const previousCourses=saved('lumi-default-courses',[]);previousCourses.forEach((c,i)=>{if(courses[i])Object.assign(courses[i],c)});
videoTime=saved('lumi-video-position',125);
const originalThemeRender=renderThemeOptions;
// Header button now states its actual action on both layouts.
const appearanceButton=document.querySelector('.topright .iconbtn');
if(appearanceButton){appearanceButton.classList.add('appearance-trigger');appearanceButton.title='Đổi giao diện';appearanceButton.setAttribute('aria-label','Giao diện: sáng, tối hoặc dịu mắt');appearanceButton.innerHTML=icon('palette')+'<span>Giao diện</span>'}
const sideNav=document.querySelector('.sidebar nav');if(sideNav)sideNav.insertAdjacentHTML('beforeend',`<button class="navitem" data-nav="hub" onclick="go('hub')">${icon('spark')}Chức năng</button>`);
const bottomNav=document.querySelector('.bottomnav');if(bottomNav){const settingsBtn=bottomNav.querySelector('[data-nav="personal"]');if(settingsBtn)settingsBtn.insertAdjacentHTML('beforebegin',`<button data-nav="hub" onclick="go('hub')">${icon('spark')}Chức năng</button>`)}
render();
